Load Records Into Table.code:
// Insert many rows into a table. Large arrays are split into batches.
insert(
  // 1) Target table.
  'household_visits',
  // 2) One object per row; keys must match column names.
  $.data.visits.map(v => ({
    visit_id: v.id,
    household_id: v.householdId,
    district: v.district,
    visit_date: v.visitDate,
    chw_id: v.chwId,
  })),
  // 3) Options.
  { batchSize: 500 }
);

Insert Single Record.code:
// Insert a single row.
insert('referrals', {
  referral_id: $.data.referralId,
  facility_code: $.data.facilityCode,
  reason: $.data.reason,
  referred_at: $.data.referredAt,
});

Create Table If Missing.code:
// Create a table if it does not already exist.
query(`
  CREATE TABLE IF NOT EXISTS household_visits (
    visit_id VARCHAR PRIMARY KEY,
    household_id VARCHAR,
    district VARCHAR,
    visit_date DATE,
    chw_id VARCHAR
  )
`);

Upsert Rows From Staging Table.code:
// Insert new rows and update existing ones, matched on the primary key.
query(`
  INSERT OR REPLACE INTO household_visits
  SELECT visit_id, household_id, district, visit_date, chw_id
  FROM household_visits_staging
`);

Get Rows Changed Since Date.code:
// Select recent rows and include the SQL in the response for debugging.
query(
  `SELECT * FROM referrals WHERE referred_at >= '${$.data.since}' ORDER BY referred_at`,
  { writeSql: true }
);
